<?php $title='Your overview';require __DIR__.'/header.php';?><div class="workspace"><?php require __DIR__.'/sidebar.php';?><section class="workspace-content"><div class="eyebrow">A LITTLE KINDNESS, EVERY DAY</div><div class="section-heading"><div><h1>Hello, <?=e($u['name'])?>.</h1><p>Here is what is happening in your MealBridge community.</p></div><?php if($u['role']==='donor'):?><a class="button" href="<?=url('donor/add-donation.php')?>">+ Share food</a><?php endif;?></div><?php
