$tot=query("SELECT COUNT(*) total,COALESCE(SUM(status='accepted'),0) accepted,COALESCE(SUM(status='collected'),0) collected FROM donations WHERE $where")->fetch();?><div class="dashboard-stats"><?php foreach(['total'=>'Total donations','accepted'=>'Awaiting collection','collected'=>'Completed collections'] as $k=>$v):?><article class="panel"><?=icon('box')?><strong><?=(int)$tot[$k]?></strong><span><?=$v?></span></article><?php endforeach;?></div><?php if($u['role']==='admin'):?><div class="notice"><b><?=query("SELECT COUNT(*) FROM users WHERE status='pending'")->fetchColumn()?> registrations awaiting review.</b> <a href="<?=url('admin/users.php')?>">Review accounts →</a></div><?php endif;?><div class="section-heading"><h2>Recent donations</h2></div><?php cards(query("SELECT * FROM donations WHERE $where ORDER BY id DESC LIMIT 6")->fetchAll());?></section></div><?php require __DIR__.'/footer.php';?>